fn v2_response_retreat_stance(self, version, rnd, player, data, debug) -> BattleSubPlanGoal

// L14 --------------------------------------------------------------
if version < 2 { return RunAway }                 // IR: icmp ult i64 %0, 2 -> block 130, tag 4

// L17 --------------------------------------------------------------
team = player.info.team                            // player+0x930, bounds-check(len=2), 넘으면 panic_bounds_check
pos  = player.info.position.as_index()             // player+0x9c0, i32(range 0..5) -> zext
cache = data.cache                                 // data+0x0
champ = cache.player_champion[team][pos]           // cache+0x1e0, [[Option<&Entity>;5];2], 팀 stride 40B
if champ == null { return RunAway }                // Option<&Entity> = 널포인터 니치

// L20~L24 ----------------------------------------------------------
enemy = 1 - team
slots = &cache.player_champion[enemy][0..5]        // iter_champions(cache, enemy) 인라인 결과 = (ptr, len 5)
nearest = slots.iter()
    .filter_map(|o| o)                             // null 슬롯 제거
    .filter(|c| {                                  // engage.rs closure$0, 본문은 m12.ll:41916~42000
        // L21
        if !data.blackboard[1 - player.info.team].is_recent_visible(cache.game, player, c) { return false }
        // L22
        if game_ai::plan_legacy::old::fight_model::is_ignored_well_enemy(version, player, c) { return false }
        // L23
        c.distance_sq(champ) < 40000000001         // = 200000^2 + 1  <=>  거리 <= 200000 (6.25셀)
    })
    .min_by_key(|c| c.distance_sq(champ))          // L24

// IR 상 세부: 첫 통과 원소를 찾는 부분이 슬롯 5개(+0/+8/+16/+24/+32)로 완전 언롤돼 있고,
// 그 원소의 distance_sq 를 초기 누적값으로 만들어 나머지를 Map/Filter/FilterMap fold(m12.ll:12391)에 넘긴다.
// 5개 모두 탈락하면 block 76 -> RunAway.

// L25 --------------------------------------------------------------
let Some(nearest) = nearest else { return RunAway }

// L26~L30 ----------------------------------------------------------
near_enemies: Vec<&Entity, &Bump> =
    Vec::from_iter_in(
        slots.iter().filter_map(|o| o).filter(|c| {   // engage.rs closure$2, m12.ll:42001~42085
            // L28 / L29 / L30 — closure$0 과 술어 3개가 동일하고 거리 임계만 다르다
            data.blackboard[1 - player.info.team].is_recent_visible(cache.game, player, c)
            && !is_ignored_well_enemy(version, player, c)
            && c.distance_sq(champ) < 22500000001    // = 150000^2 + 1  <=>  거리 <= 150000 (4.6875셀)
        }),
        data.context.pool)                            // context+0x0 = &Bump

// L31~L32 ----------------------------------------------------------
die = game_ai::fight_check::check_kill_die_tick(
          version, rnd, data, player, champ,
          near_enemies,                               // 위에서 만든 Vec
          Vec::new_in(data.context.pool),             // L32: 항상 비어 있는 Vec(len=0,cap=0, ptr=dangling 8)
          debug)                                      // -> i64

// L33 --------------------------------------------------------------
if die > data.context.setting.tick_per_second {       // context+0x8 -> setting+0x12f8
    // L36
    return KitingBack { focus: nearest.id }           // tag 3, payload = nearest+0x5c0
}
// L38
return RunAway                                        // tag 4

// 요약: '1초보다 오래 버틸 수 있으면' 가장 가까운(200000 이내·시야에 잡히는·무시대상 아닌) 적을
//        focus 삼아 뒤로 빼며 싸우고(KitingBack), 그보다 빨리 죽을 것 같으면 그냥 도망친다(RunAway).
